ALTER TABLE spots DROP CONSTRAINT chk_spots_kind;
ALTER TABLE spots ADD CONSTRAINT chk_spots_kind CHECK (kind IN ('SHRINE_TEMPLE','PARK_GARDEN','AMUSEMENT','VIEWPOINT','HISTORIC','MUSEUM','MARKET','ONSEN'));
UPDATE spots SET kind = 'ONSEN' WHERE name_ja = '道後温泉本館';

