INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('미야지마 로프웨이', '宮島ロープウエー', 'VIEWPOINT', '広島県', '廿日市市', 34.290800, 132.330200, 'FIXED', '09:00', '16:00', NULL, '상행 9:00~16:00, 하행 막차 16:30. 악천후·연 2회 정기 정비 때 운휴. 혼잡 시 웹 예약 필요', '왕복 2,000엔, 편도 1,100엔 (초등학생 왕복 1,000엔)', '모미지다니역에서 시시이와역까지 로프웨이 2개를 갈아타고 약 15분. 세계유산 미센 원시림 위를 지나 표고 433m까지 오른다.', '모미지다니 공원 입구에서 산기슭역까지 무료 셔틀버스가 있다. 시시이와역에서 미센 정상까지는 걸어서 간다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('미야지마 수족관 (미야지마린)', '宮島水族館', 'AMUSEMENT', '広島県', '廿日市市', 34.293400, 132.315700, 'FIXED', '09:00', '17:00', NULL, '최종 입관 16:00. 정비·점검 임시 휴관 있음', '1,420엔 (초중학생 710엔, 4세 이상 유아 400엔)', '세토나이카이 생물을 중심으로 350종 넘게 전시하는 수족관. 미야지마 경관에 맞춘 기와지붕 건물이다.', '이쓰쿠시마 신사 출구에서 걸어서 약 5분이고, 강치 라이브와 상괭이를 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다이쇼인', '大聖院', 'SHRINE_TEMPLE', '広島県', '廿日市市', 34.293200, 132.318500, 'FIXED', '08:00', '17:00', NULL, '매월 1일은 5:30 개문, 1/1은 0:00부터. 연중무휴', '무료', '806년 고보 대사(구카이)가 열었다고 전하는 미야지마에서 가장 오래된 절. "일본 3대 액막이 개운 대사" 중 하나로 꼽힌다.', '좌선·사경 같은 체험 프로그램이 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('호코쿠 신사 (센조카쿠)', '豊国神社', 'HISTORIC', '広島県', '廿日市市', 34.296800, 132.320300, 'FIXED', '08:30', '16:30', NULL, '무휴', '100엔', '1587년 도요토미 히데요시가 세우게 한 대경당. 히데요시가 죽어 공사가 멈춘 탓에 천장도 없는 미완성 상태로 남아 있고, 다다미 857장 넓이라 "센조카쿠(천 장 누각)"라 불린다.', '언덕 위라 툇마루에서 이쓰쿠시마 신사가 내려다보인다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이나사 해변', '稲佐の浜', 'VIEWPOINT', '島根県', '出雲市', 35.398300, 132.677700, 'ALWAYS', NULL, NULL, NULL, '견학 자유', '무료', '국가 이양 신화의 무대로 전해지는 해변. 음력 10월 "가미아리즈키"에 전국의 신을 맞이하는 신사(神事)가 열린다.', '"일본 해변 100선"에 든 노을 명소다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('옛 다이샤역', '旧大社駅', 'HISTORIC', '島根県', '出雲市', 35.392300, 132.692800, 'FIXED', '09:00', '16:30', 'WED', '수요일(공휴일이면 다음 평일) 휴관', '300엔', '1990년 폐선된 JR 다이샤선의 종착역. 1924년에 지은 지금의 역사는 서양식 트러스 구조에 일본식 지붕을 합친 근대 일본풍 건축으로 국가 중요문화재다.', '부지 안에 증기기관차가 전시돼 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이즈모 히노미사키 등대', '出雲日御碕灯台', 'VIEWPOINT', '島根県', '出雲市', 35.433200, 132.630800, 'FIXED', '09:00', '16:30', NULL, '토·일·공휴일은 17:00까지(10~2월은 매일 16:30). 12:00~13:00 점심 휴무, 입장 20분 전 마감. 악천후 휴관', '참관 기부금 300엔 (중학생 이상)', '1903년 완공, 높이 43.65m로 석조 등대 중 일본에서 가장 높다. 163단 나선계단 위 전망대에서 동해가 360도로 보인다.', '근처 히노미사키 신사와 해안 산책로를 함께 돌기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히노미사키 신사', '日御碕神社', 'SHRINE_TEMPLE', '島根県', '出雲市', 35.430500, 132.632000, 'ALWAYS', NULL, NULL, NULL, '경내 자유', '무료', '아마테라스를 모신 히시즈미노미야와 스사노오를 모신 가미노미야로 이뤄진 신사. "일본의 밤을 지킨다"고 전해지며, 지금의 사전은 도쿠가와 이에미쓰가 지었다.', '주홍색 누문과 사전이 소나무 숲에 둘러싸여 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쿠시마성 박물관', '徳島市立徳島城博物館', 'MUSEUM', '徳島県', '徳島市', 34.075900, 134.558200, 'FIXED', '09:30', '17:00', 'MON', '입관 16:30까지. 월요일(공휴일이면 개관)·공휴일 다음 날·연말연시 휴관', '300엔 (고교·대학생 200엔, 중학생 이하 무료)', '도쿠시마성 터(도쿠시마 중앙공원)에 있는 역사박물관. 현존 최고(最古)의 일본 배로 알려진 중요문화재 "센잔마루"와 성 어전 복원 모형이 있다.', '입관하면 옛 도쿠시마성 오모테고텐 정원도 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('효탄지마 주유선', 'ひょうたん島周遊船', 'VIEWPOINT', '徳島県', '徳島市', 34.073300, 134.553800, 'FIXED', '11:00', '15:40', NULL, '7·8월은 17:00~19:40도 운항. 1/1 휴무. 약 30분 코스', '300엔 (료고쿠바시 승선장 기준, 어린이 150엔)', '두 강에 둘러싸인 도쿠시마 중심가 "효탄지마(표주박섬)"를 배로 한 바퀴 도는 약 30분 크루즈. 다리 19개 밑을 지난다.', '물이 불면 다리 밑을 아슬아슬하게 지나가는 게 재미 포인트다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쿠시마 현립박물관 (문화의 숲)', '徳島県立博物館', 'MUSEUM', '徳島県', '徳島市', 34.046400, 134.523600, 'FIXED', '09:30', '17:00', 'MON', '월요일(공휴일이면 다음 날)·연말연시 휴관', '상설전 200엔 (고교·대학생 100엔, 초중학생 50엔)', '문화의 숲 종합공원 안에 있는 현립 박물관.', '같은 공원에 근대미술관과 도리이 류조 기념박물관이 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도고 온천 별관 아스카노유', '道後温泉別館 飛鳥乃湯泉', 'ONSEN', '愛媛県', '松山市', 33.851000, 132.786000, 'FIXED', '06:00', '23:00', NULL, '1층 욕실 기준(입장 22:30까지), 코스마다 다름. 12월에 하루 임시 휴관', '1층 욕실 610엔 (2층 휴게실 포함 1,280엔부터)', '2017년에 문을 연 도고 온천의 세 번째 공중목욕탕. 아스카 시대 건축 양식을 들여왔고, 에히메 전통공예로 꾸민 관내가 미술관 같다.', '외탕 중 노천탕이 있는 곳은 여기뿐이다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('언덕 위의 구름 뮤지엄', '坂の上の雲ミュージアム', 'MUSEUM', '愛媛県', '松山市', 33.843400, 132.769500, 'FIXED', '09:00', '18:30', 'MON', '입관 18:00까지. 월요일(공휴일이면 개관) 휴관, 2월 하순 전시 교체 휴관', '500엔 (고교생 250엔, 중학생 이하 무료)', '마쓰야마 출신 마사오카 시키와 아키야마 형제를 그린 시바 료타로의 소설 『언덕 위의 구름』을 주제로 한 뮤지엄. 건물은 안도 다다오가 설계했다.', '신문 연재 1,296회분을 벽에 전시한 공간이 볼거리다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시키 기념박물관', '松山市立子規記念博物館', 'MUSEUM', '愛媛県', '松山市', 33.849200, 132.785100, 'FIXED', '09:00', '18:00', 'TUE', '5/1~10/31 기준, 11/1~4/30은 17:00까지. 입관 30분 전 마감. 화요일(공휴일이면 다음 날) 휴관', '400엔 (초중고생 무료)', '근대 하이쿠를 확립한 마사오카 시키를 소개하는 문학 박물관. 시키와 나쓰메 소세키가 함께 살았던 "구다부쓰안"을 복원해 두었다.', '2024년 상설전 리뉴얼로 퀴즈 코너와 자작 하이쿠 단자쿠 인쇄 코너가 생겼다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spot_hours (spot_id, start_md, end_md, open_time, close_time, closed_days, is_closed) SELECT id, '11-01', '04-30', '09:00', '17:00', NULL, 0 FROM spots WHERE name_ja = '松山市立子規記念博物館';
